        dest[destOffset + 5] = Math.fma(_self11, _t1, _self12 * _t0);
        dest[destOffset + 6] = Math.fma(_self12, _t1, -(_self11 * _t0));
        dest[destOffset + 7] = _self13;
        dest[destOffset + 8] = _self20;
        dest[destOffset + 9] = Math.fma(_self21, _t1, _self22 * _t0);
